"""Generate numeric account service routes for both independent native runtimes."""
import argparse
import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
source = ROOT / "native/AccountsProtocol/routes.json"
routes = json.loads(source.read_text())
ids = [row[0] for rows in routes.values() for row in rows]
if len(ids) != len(set(ids)) or any(value in (0, 1, 200, 201) for value in ids):
    raise ValueError("Duplicate or reserved account route")
header = "// <auto-generated/>\n#nullable enable\nusing Nexa.Services.Accounts;\nusing Nexa.Services.Foundation;\nusing Nexa.Native.Services.Wire;\nusing Nexa.Xsr;\n\n"
module = header + "namespace Nexa.Native.Accounts;\n\ninternal sealed partial class AccountsSession\n{\n    private async Task DispatchAsync(int operation, ServiceWireReader reader, ServiceWireWriter writer, CancellationToken token)\n    {\n        switch (operation)\n        {\n"
client = header + "namespace Nexa.Native.Accounts.Client;\n\npublic sealed partial class NativeAccountService\n{\n"
composition = "// <auto-generated/>\n#nullable enable\n#if NEXA_NATIVE_SERVICES\nusing Nexa.Native.Accounts.Client;\nusing Nexa.Services.Accounts;\nusing Nexa.Services.Foundation;\nusing Nexa.Xsr;\nusing Nexa.Xsr.Runtime;\n\nnamespace Nexa.Services.Composition;\n\ninternal static class NativeAccountRouters\n{\n    internal static (XsrCommandRouter Commands, XsrQueryRouter Queries) Create(NativeAccountService account, IXsrDispatchObserver? observer)\n    {\n        XsrCommandRouterBuilder commands = new();\n        XsrQueryRouterBuilder queries = new();\n"
for operation, request, route, handler in routes["commands"]:
    module += f"            case {operation}:\n            {{\n                var command = reader.{request}() ?? throw new InvalidDataException(\"Missing account command.\"); reader.End();\n                var result = {handler}; writer.XsrError(result.Error); return;\n            }}\n"
    client += f"    public ValueTask<XsrResult> Dispatch{request}Async({request} command, CancellationToken token = default) =>\n        CommandAsync({operation}, writer => writer.{request}(command), token);\n"
    # Foundation keeps its existing roster routes in its own router; onboarding exposes
    # exactly the same ten routes in managed and native compositions.
    if operation < 20:
        composition += f"        commands.Register<{request}>({route}, account.Dispatch{request}Async);\n"
for operation, request, response, route, handler in routes["queries"]:
    codec = "IReadOnlyList_WardrobeCatalogSite" if response.startswith("IReadOnlyList") else response
    module += f"            case {operation}:\n            {{\n                var query = reader.{request}() ?? throw new InvalidDataException(\"Missing account query.\"); reader.End();\n                var result = await {handler}(query, token).ConfigureAwait(false);\n                writer.XsrError(result.Error); if (result.IsSuccess) writer.{codec}(result.Value); return;\n            }}\n"
    client += f"    public ValueTask<XsrResult<{response}>> Query{request}Async({request} query, CancellationToken token = default) =>\n        QueryAsync({operation}, writer => writer.{request}(query), reader => reader.{codec}()!, token);\n"
    composition += f"        queries.Register<{request}, {response}>({route}, account.Query{request}Async);\n"
module += "            default: throw new InvalidDataException(\"Unknown account service route.\");\n        }\n    }\n}\n"
client += "}\n"
composition += "        return (commands.Build(observer ?? new Observer()), queries.Build(observer ?? new Observer()));\n    }\n    private sealed class Observer : IXsrDispatchObserver { public void OnCompleted(XsrDispatchObservation observation) { } }\n}\n#endif\n"
schema = "// <auto-generated/>\nnamespace Nexa.Native.Accounts.Wire;\ninternal static class AccountRouteSchema\n{\n    internal const string Fingerprint = \"" + hashlib.sha256(json.dumps(routes, sort_keys=True, separators=(",", ":")).encode()).hexdigest().upper() + "\";\n}\n"
outputs = {"native/Nexa.Native.Accounts/AccountsSession.Routes.Generated.cs": module,
           "native/Nexa.Native.Accounts.Client/NativeAccountService.Routes.Generated.cs": client,
           "Nexa.Services.Composition/Composition/NativeAccountRouters.Generated.cs": composition,
           "native/AccountsProtocol/AccountRouteSchema.Generated.cs": schema}
parser = argparse.ArgumentParser(description=__doc__)
parser.add_argument("--check", action="store_true")
args = parser.parse_args()
for path, contents in outputs.items():
    target = ROOT / path
    if args.check:
        if target.read_text() != contents:
            raise SystemExit("Stale generated account routes: " + path)
    else:
        target.write_text(contents)
